{"content": "using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Oocx.TfPlan2Md.RenderTargets.AzureDevOps;

/// <summary>
/// Diff formatter for Azure DevOps Pull Request rendering using inline HTML diffs.
/// </summary>
/// <remarks>
/// Azure DevOps supports rich HTML rendering in markdown, allowing for styled
/// inline diffs with character-level highlighting. This provides a more detailed
/// visual representation of changes than simple +/- notation.
/// Related feature: docs/features/047-provider-code-separation/specification.md.
/// </remarks>
internal sealed class AzureDevOpsDiffFormatter : IDiffFormatter
{
    /// <inheritdoc />
    public string FormatDiff(string? before, string? after)
    {
        var beforeValue = before ?? string.Empty;
        var afterValue = after ?? string.Empty;

        // Return empty when both values are null or empty
        if (string.IsNullOrEmpty(beforeValue) && string.IsNullOrEmpty(afterValue))
        {
            return string.Empty;
        }

        // Return the unchanged value wrapped in code when both are identical
        if (string.Equals(beforeValue, afterValue, StringComparison.Ordinal))
        {
            return WrapInlineCode(EscapeMarkdown(afterValue));
        }

        // Build inline diff with HTML styling
        return WrapInlineDiffCode(BuildInlineDiffTable(beforeValue, afterValue));
    }

    /// <summary>
    /// Wraps content in a minimal inline code HTML tag, returning an empty string when the content is empty.
    /// </summary>
    /// <param name="content">Content to wrap.</param>
    /// <returns>Inline code HTML string.</returns>
    private static string WrapInlineCode(string content)
    {
        return string.IsNullOrEmpty(content) ? string.Empty : $"<code>{content}</code>";
    }

    /// <summary>
    /// Wraps inline diff content in a block-style code tag suitable for markdown tables.
    /// </summary>
    /// <param name="content">Diff content to wrap.</param>
    /// <returns>HTML block containing the diff content.</returns>
    private static string WrapInlineDiffCode(string content)
    {
        return string.IsNullOrEmpty(content)
            ? string.Empty
            : $"<code style=\"display:block; white-space:normal; padding:0; margin:0;\">{content}</code>";
    }

    /// <summary>
    /// Creates an inline diff representation suitable for embedding in markdown tables.
    /// </summary>
    /// <param name="before">Original value.</param>
    /// <param name="after">Updated value.</param>
    /// <returns>Table-friendly inline diff string.</returns>
    private static string BuildInlineDiffTable(string before, string after)
    {
        var block = BuildInlineDiff(before, after);
        var content = block
            .Replace("<pre style=\"font-family: monospace; line-height: 1.5;\"><code>", string.Empty, StringComparison.Ordinal)
            .Replace("</code></pre>", string.Empty, StringComparison.Ordinal)
            .Replace("display: block;", "display: inline-block;", StringComparison.Ordinal);

        content = content.Replace("\r", string.Empty, StringComparison.Ordinal).Replace("\n", "<br>", StringComparison.Ordinal);

        if (content.EndsWith("<br>", StringComparison.Ordinal))
        {
            content = content[..^4];
        }

        return content;
    }

    /// <summary>
    /// Builds an inline HTML diff block with styled line-level changes.
    /// </summary>
    /// <param name="before">Original value.</param>
    /// <param name="after">Updated value.</param>
    /// <returns>HTML block showing line and character-level differences.</returns>
    private static string BuildInlineDiff(string before, string after)
    {
        var beforeLines = SplitLines(before);
        var afterLines = SplitLines(after);
        var diff = MarkdownGeneration.DiffComputation.BuildLineDiff(beforeLines, afterLines);
        var sb = new StringBuilder();
        sb.Append("<pre style=\"font-family: monospace; line-height: 1.5;\"><code>");

        var index = 0;
        while (index < diff.Count)
        {
            var entry = diff[index];
            if (entry.Kind == MarkdownGeneration.DiffKind.Unchanged)
            {
                sb.Append(HtmlEncode(entry.Text));
                sb.Append('\n');
                index++;
                continue;
            }

            if (entry.Kind == MarkdownGeneration.DiffKind.Removed && index + 1 < diff.Count && diff[index + 1].Kind == MarkdownGeneration.DiffKind.Added)
            {
                var addEntry = diff[index + 1];
                AppendStyledLineWithCharDiff(sb, entry.Text, addEntry.Text, removed: true);
                AppendStyledLineWithCharDiff(sb, addEntry.Text, entry.Text, removed: false);
                index += 2;
                continue;
            }

            if (entry.Kind == MarkdownGeneration.DiffKind.Removed)
            {
                AppendStyledLine(sb, entry.Text, removed: true);
                index++;
                continue;
            }

            if (entry.Kind == MarkdownGeneration.DiffKind.Added)
            {
                AppendStyledLine(sb, entry.Text, removed: false);
                index++;
            }
        }

        sb.Append("</code></pre>");
        return sb.ToString();
    }

    /// <summary>
    /// Splits content into lines, normalizing carriage returns.
    /// </summary>
    /// <param name="value">Content to split.</param>
    /// <returns>Array of lines.</returns>
    private static string[] SplitLines(string value)
    {
        return value.Replace("\r", string.Empty, StringComparison.Ordinal)
            .Split('\n', StringSplitOptions.None);
    }

    /// <summary>
    /// Appends a styled line prefixing removal or addition markers with consistent coloring.
    /// </summary>
    /// <param name="sb">String builder receiving the styled content.</param>
    /// <param name="line">Line text to render.</param>
    /// <param name="removed">True when the line represents a removal.</param>
    private static void AppendStyledLine(StringBuilder sb, string line, bool removed)
    {
        var lineStyle = removed
            ? "background-color: #fff5f5; border-left: 3px solid #d73a49; color: #24292e; display: block; padding-left: 8px; margin-left: 0;"
            : "background-color: #f0fff4; border-left: 3px solid #28a745; color: #24292e; display: block; padding-left: 8px; margin-left: 0;";

        sb.Append("<span style=\"");
        sb.Append(lineStyle);
        sb.Append('"');
        sb.Append('>');
        sb.Append(removed ? "- " : "+ ");
        sb.Append(HtmlEncode(line));
        sb.AppendLine("</span>");
    }

    /// <summary>
    /// Appends a styled line while highlighting character-level differences against another line.
    /// </summary>
    /// <param name="sb">String builder receiving the styled content.</param>
    /// <param name="line">Line to render.</param>
    /// <param name="otherLine">Line to compare for highlighting common characters.</param>
    /// <param name="removed">True when rendering a removed line.</param>
    private static void AppendStyledLineWithCharDiff(StringBuilder sb, string line, string otherLine, bool removed)
    {
        var pairs = MarkdownGeneration.LcsComputation.ComputeLcsPairs(line, otherLine);
        var commonMask = BuildCommonMask(line.Length, pairs.Select(p => p.BeforeIndex));
        var highlightColor = removed ? "#ffc0c0" : "#acf2bd";
        var lineStyle = removed
            ? "background-color: #fff5f5; border-left: 3px solid #d73a49; color: #24292e; display: block; padding-left: 8px; margin-left: 0;"
            : "background-color: #f0fff4; border-left: 3px solid #28a745; color: #24292e; display: block; padding-left: 8px; margin-left: 0;";

        sb.Append("<span style=\"");
        sb.Append(lineStyle);
        sb.Append('"');
        sb.Append('>');
        sb.Append(removed ? "- " : "+ ");
        sb.Append(ApplyCharHighlights(line, commonMask, highlightColor));
        sb.AppendLine("</span>");
    }

    /// <summary>
    /// Builds a boolean mask indicating which character positions are common between two strings.
    /// </summary>
    /// <param name="length">Length of the mask to build.</param>
    /// <param name="commonIndices">Enumerable of indices that are common.</param>
    /// <returns>Boolean array where true indicates a common character position.</returns>
    private static bool[] BuildCommonMask(int length, IEnumerable<int> commonIndices)
    {
        var mask = new bool[length];
        foreach (var index in commonIndices)
        {
            if (index >= 0 && index < length)
            {
                mask[index] = true;
            }
        }

        return mask;
    }

    /// <summary>
    /// Highlights differing character regions using span tags while preserving common characters.
    /// </summary>
    /// <param name="line">Line to render.</param>
    /// <param name="commonMask">Boolean mask indicating which positions are shared.</param>
    /// <param name="highlightColor">Background color for differing segments.</param>
    /// <returns>HTML string with highlighted differences.</returns>
    private static string ApplyCharHighlights(string line, bool[] commonMask, string highlightColor)
    {
        var sb = new StringBuilder();
        var inHighlight = false;

        for (var i = 0; i < line.Length; i++)
        {
            var isCommon = i < commonMask.Length && commonMask[i];
            if (!isCommon && !inHighlight)
            {
                sb.Append("<span style=\"background-color: ");
                sb.Append(highlightColor);
                sb.Append("; color: #24292e;\">");
                inHighlight = true;
            }
            else if (isCommon && inHighlight)
            {
                sb.Append("</span>");
                inHighlight = false;
            }

            sb.Append(HtmlEncode(line[i].ToString()));
        }

        if (inHighlight)
        {
            sb.Append("</span>");
